    {
      "number": 1,
      "parent": null,
      "raw": "Torp, lägenhet, verk och inrättningar m. m. under ovanstående fastighet. Personens för- och tillnamn samt familjeställning, ävensom personens titel, om annan än den i kol. 2 angivna."
    },
    {
      "number": 2,
      "parent": null,
      "raw": "Yrke (tjänst, näringsfång) Stam (främmande). Lyte (sinnessjukdom, sinnesslöhet, blindhet, dövstumhet, fallandesot)."
    },
    {
      "number": 3,
      "parent": "Född",
      "raw": "år"
    },
    {
      "number": 4,
